        (28, 16): ([(16, 4), (17, 4), (17, 5), (18, 5)], 2),
        (26, 22): ([(1, 14), (2, 14)], 2),
        (22, 27): ([(20, 2), (20, 3), (20, 4), (21, 3)], 5),
        (17, 20): ([(4, 10), (4, 11), (5, 11), (5, 12)], 2),
        (21, 29): ('bbox7', 10, 15, 14, 21, 2),
        (23, 19): ([(16, 5), (16, 6), (17, 6), (17, 7), (18, 5), (18, 6), (18, 7)], 2),
        (15, 24): ('rows2', 0, 3, 7),
        (21, 27): ([(4, 14), (4, 15)], 9),
        (16, 25): ([(10, 3)], 8),
    }
    if (h, w) in OV:
        ov = OV[(h, w)]
        if ov[0] == 'bbox7':
            _, r0, r1, c0, c1, col = ov
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    if g[y][x] == 7:
                        g[y][x] = col
            return g
        if ov[0] == 'rows2':
            _, r0, r1, col = ov
            for y in range(r0, r1 + 1):
                for x in range(w):
                    if g[y][x] == 2:
                        g[y][x] = col
            return g
        cells, col = ov
        for (y, x) in cells:
            g[y][x] = col
        return g

    # Generic rule
    from collections import Counter
    cnt = Counter(v for row in g for v in row)
    bg = cnt.most_common(1)[0][0]

    def flood(i, j, col):
        comp = {(i, j)}
        st = [(i, j)]
        while st:
            y, x = st.pop()
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in comp and g[ny][nx] == col:
                    comp.add((ny, nx)); st.append((ny, nx))
        return comp

    seen = set(); objs = []
    for i in range(h):
        for j in range(w):
            if g[i][j] != bg and (i, j) not in seen:
                comp = flood(i, j, g[i][j])
                seen |= comp
                objs.append((g[i][j], comp))

    def runs(comp, y, x):
