        while (y, xx) in comp: hr += 1; xx -= 1
        xx = x + 1
        while (y, xx) in comp: hr += 1; xx += 1
        vr = 1; yy = y - 1
        while (yy, x) in comp: vr += 1; yy -= 1
        yy = y + 1
        while (yy, x) in comp: vr += 1; yy += 1
        return hr, vr

    best = None
    for col, comp in objs:
        for (y, x) in comp:
            hr, vr = runs(comp, y, x)
            if min(hr, vr) >= 2 and len(comp) == hr + vr - 1:
                if best is None or len(comp) > best[0]:
                    best = (len(comp), col, comp, y, x, hr, vr)
    if best is None:
        return g
    _, C, comp, cy, cx, hr, vr = best
    dy = 1 if any((y, cx) in comp for y in range(cy + 1, h)) else -1
    dx = 1 if any((cy, x) in comp for x in range(cx + 1, w)) else -1
    oy, ox = -dy, -dx

    cands = []
    for col2, comp2 in objs:
