        n = len(comp2)
        if n >= 2 and n == max(bw, bh):
            continue  # straight line
        if bw * bh == n and bw >= 2 and bh >= 2:
            continue  # solid rectangle
        d = min((y - cy) ** 2 + (x - cx) ** 2 for y, x in inside)
        cands.append((d, comp2))
    if not cands:
        return g
    cands.sort(key=lambda c: c[0])
    for y, x in cands[0][1]:
        g[y][x] = C
    return g
